:root{--bg:#0f1720;--panel:#17212c;--line:#263444;--text:#e8eef5;--muted:#8fa1b3;--accent:#4cc2b0;--good:#58d68d;--bad:#f0866b}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:48px 32px 32px}
header{margin-bottom:36px;border-left:4px solid var(--accent);padding-left:18px}
h1{margin:0;font-size:40px;letter-spacing:-.02em;font-weight:700}
.sub{margin:4px 0 0;font-size:18px;color:var(--muted)}
section{margin-bottom:40px}
h2{margin:0 0 16px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:600}
.num{font-variant-numeric:tabular-nums}
